/* DREEK face: an 8-bit luminance map of the source portrait, 220x300,
   feathered to black at the edges so the head dissolves instead of ending on a
   crop rectangle. Base64 of raw grayscale bytes - no image decoder needed. */

export const FACE_W = 220;
export const FACE_H = 300;

const B64 = "";

export const FACE = (() => {
  const bin = atob(B64);
  const a = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
  return a;
})();

// Bilinear sample in normalised coordinates. Outside the map reads as black.
export function faceAt(u, v) {
  if (u < 0 || u > 1 || v < 0 || v > 1) return 0;
  const x = u * (FACE_W - 1), y = v * (FACE_H - 1);
  const x0 = x | 0, y0 = y | 0;
  const x1 = x0 + 1 < FACE_W ? x0 + 1 : x0;
  const y1 = y0 + 1 < FACE_H ? y0 + 1 : y0;
  const fx = x - x0, fy = y - y0;
  const top = FACE[y0 * FACE_W + x0] + (FACE[y0 * FACE_W + x1] - FACE[y0 * FACE_W + x0]) * fx;
  const bot = FACE[y1 * FACE_W + x0] + (FACE[y1 * FACE_W + x1] - FACE[y1 * FACE_W + x0]) * fx;
  return (top + (bot - top) * fy) / 255;
}
